INSERT INTO race_model (Race_ID,race_Name,race_Ability_Score,race_Features,race_Age_Adult,race_Age_Max,race_Skills,race_Height,race_Size,race_Speed,race_Languages,race_creature_Type) VALUES (3,'Bugbear','Str+2, Dex+1','Darkvision, Fey Ancestry, Long-Limbed, Powerful Build, Sneaky, Suprise Attack',16,80,'Stealth','6-8','medium','30w','Common, 1','Humanoid, Goblinoid');
