INSERT INTO spell_model(Spell_Id,Spell_Name,spell_Level,spell_School,spell_Casting_Time,spell_Range,spell_Components,spell_Duration,spell_Description,spell_Level_Up_Scale,spell_Availability) VALUES (1,'Acid Splash','Cantrip','Conjuration','1 action','60 feet','V, S','Instantaneous','You hurl a bubble of acid. Choose one creature you can see within range, or choose two creatures you can see within range that are within 5 feet of each other. A target must succeed on a Dexterity saving throw or take 1d6 acid damage.','This spell''s damage increases by 1d6 when you reach 5th level (2d6), 11th level (3d6), and 17th level (4d6).','Artificer, Sorcerer, Wizard, Water Genasi');
INSERT INTO spell_model(Spell_Id,Spell_Name,spell_Level,spell_School,spell_Casting_Time,spell_Range,spell_Components,spell_Duration,spell_Description,spell_Level_Up_Scale,spell_Availability) VALUES (2,'Blade Ward','Cantrip','Abjuration','1 action','Self','V, S','1 round','You extend your hand and trace a sigil of warding in the air. Until the end of your next turn, you have resistance against bludgeoning, piercing, and slashing damage dealt by weapon attacks.',NULL,'Bard, Sorcerer, Warlock, Wizard, Earth Genasi');
INSERT INTO spell_model(Spell_Id,Spell_Name,spell_Level,spell_School,spell_Casting_Time,spell_Range,spell_Components,spell_Duration,spell_Description,spell_Level_Up_Scale,spell_Availability) VALUES (3,'Chill Touch','Cantrip','Necromancy','1 action','120 feet','V, S','1 round','You create a ghostly, skeletal hand in the space of a creature within range. Make a ranged spell attack against the creature to assail it with the chill of the grave. On a hit, the target takes 1d8 necrotic damage, and it can''t regain hit points until the start of your next turn. Until then, the hand clings to the target. If you hit an undead target, it also has disadvantage on attack rolls against you until the end of your next turn.','This spell''s damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8).','Sorcerer, Warlock, Wizard');
INSERT INTO spell_model(Spell_Id,Spell_Name,spell_Level,spell_School,spell_Casting_Time,spell_Range,spell_Components,spell_Duration,spell_Description,spell_Level_Up_Scale,spell_Availability) VALUES (4,'Zone of Truth','2nd Level','Enchantment','1 action','60 feet','V, S','10 minutes','You create a magical zone that guards against deception in a 15-foot-radius sphere centered on a point of your choice within range. Until the spell ends, a creature that enters the spell''s area for the first time on a turn or starts its turn there must make a Charisma saving throw. On a failed save, a creature can''t speak a deliberate lie while in the radius. You know whether each creature succeeds or fails on its saving throw.An affected creature is aware of the spell and can thus avoid answering questions to which it would normally respond with a lie. Such creatures can be evasive in its answers as long as it remains within the boundaries of the truth.',NULL,'Bard, Cleric, Paladin');
INSERT INTO spell_model(Spell_Id,Spell_Name,spell_Level,spell_School,spell_Casting_Time,spell_Range,spell_Components,spell_Duration,spell_Description,spell_Level_Up_Scale,spell_Availability) VALUES (5,'Hallow','5th Level','Evocation','24 hours','Touch','V, S, M (herbs, oils, and incense worth at least 1,000 gp, which the spell consumes)','Until dispelled','You touch a point and infuse an area around it with holy (or unholy) power. The area can have a radius up to 60 feet, and the spell fails if the radius includes an area already under the effect a hallow spell. The affected area is subject to the following effects.First, celestials, elementals, fey, fiends, and undead cant enter the area, nor can such creatures charm, frighten, or possess creatures within it. Any creature charmed, frightened, or possessed by such a creature is no longer charmed, frightened, or possessed upon entering the area. You can exclude one or more of those types of creatures from this effect.Second, you can bind an extra effect to the area. Choose the effect from the following list, or choose an effect offered by the DM. Some of these effects apply to creatures in the area; you can designate whether the effect applies to all creatures, creatures that follow a specific deity or leader, or creatures of a specific sort, such as orcs or trolls. When a creature that would be affected enters the spell''s area for the first time on a turn or starts its turn there, it can make a Charisma saving throw. On a success, the creature ignores the extra effect until it leaves the area.Courage.Affected creatures can''t be frightened while in the area.Darkness.Darkness fills the area. Normal light, as well as magical light created by spells of a lower level than the slot you used to cast this spell, can''t illuminate the area.Daylight.Bright light fills the area. Magical darkness created by spells of a lower level than the slot you used to cast this spell can''t extinguish the light.Energy Protection.Affected creatures in the area have resistance to one damage type of your choice, except for bludgeoning, piercing, or slashing.Energy Vulnerability.Affected creatures in the area have vulnerability to one damage type of your choice, except for bludgeoning, piercing, or slashing.Everlasting Rest.Dead bodies interred in the area can''t be turned into undead.Extradimensional Interference.Affected creatures can''t move or travel using teleportation or by extradimensional or interplanar means.Fear.Affected creatures are frightened while in the area.Silence.No sound can emanate from within the area, and no sound can reach into it.Tongues.Affected creatures can communicate with any other creature in the area, even if they don''t share a common language.',NULL,'Cleric'); 
